+    border-bottom: 1px solid var(--line-strong);
+  }
+
+  .fleet-grid {
+    max-height: none;
+    overflow: visible;
+  }
+
+  .transcript-pane {
+    min-height: 55vh;
+    grid-template-rows: auto minmax(55vh, 1fr) auto;
+  }
+
+  .transcript-feed {
+    min-height: 55vh;
+    max-height: 70vh;
+  }
+
+  .transcript-header > .mobile-anchor,
+  .card-jump {
+    display: inline-block;
+  }
+
+  .control-pane {
+    min-height: 360px;
+    overflow: visible;
+  }
+
+  .bottom-rail {
+    position: static;
+    flex-wrap: wrap;
+  }
+
+  .utility-menu {
+    margin-left: 0;
+  }
+
+  .bottom-provenance {
+    margin-left: auto;
+  }
+
+  .routing-drawer {
+    max-height: none;
+  }
+}
+
+@media (max-width: 420px) {
+  .command-rail > * {
+    min-width: 0;
+  }
+
+  .rail-spend,
+  .rail-burn {
+    grid-template-columns: 1fr;
+  }
+
+  .provenance {
+    justify-self: start;
+  }
+
+  .fleet-grid {
+    grid-template-columns: minmax(0, 1fr);
+  }
+
+  .transcript-row {
+    grid-template-columns: 1fr;
+  }
+
+  .row-meta {
+    display: flex;
+    gap: 8px;
+  }
+
+  .row-details {
+    grid-column: 1;
+  }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  html {
+    scroll-behavior: auto;
+  }
+
+  *,
+  *::before,
+  *::after {
+    animation-duration: 0.01ms !important;
+    animation-iteration-count: 1 !important;
+    scroll-behavior: auto !important;
+    transition-duration: 0.01ms !important;
+  }
+}

